// Normalize reason_code to a known set; default to 'other' if missing/unrecognized
const known = ['angry_caller', 'out_of_scope', 'repeated_failure', 'other'];
let code = ($json.reason_code || '').toString().trim().toLowerCase();

if (!known.includes(code)) {
  code = 'other';
}

return [
  {
    json: {
      ...$json,
      reason_code_normalized: code
    }
  }
];

// Build a natural, apologetic handoff line tailored to the reason for escalation.
// This is spoken by the voice AI to the caller — keep it warm, brief, and non-technical.

const messages = {
  angry_caller: "I'm really sorry for the frustration. Let me connect you with a member of our front desk team directly — they'll follow up with you personally as soon as possible.",
  out_of_scope: "That's something our front desk team will need to help you with directly. I'll pass this along, and someone will get back to you shortly.",
  repeated_failure: "I'm sorry this hasn't been resolved yet. Let me hand this over to a team member who can take care of it properly — they'll be in touch soon.",
  other: "Let me connect you with a member of our front desk team who can help further. Someone will follow up with you shortly."
};

const code = $json.reason_code_normalized;
const message_for_caller = messages[code] || messages.other;

return [
  {
    json: {
      status: 'escalated',
      reason_code: code,
      message_for_caller,
      caller_phone: $json.caller_phone || null,
      event_id: $json.event_id || null,
      context_summary: $json.context_summary || null,
      escalated_at: new Date().toISOString()
    }
  }
];

