// Consolidate final response for the AI. Logging failures never block the caller-facing message.
const handoff = $('Build Handoff Response').first().json;

let slackOk = true;
try {
  const slackItem = $('Notify Slack').first();
  slackOk = !(slackItem && slackItem.json && slackItem.json.error);
} catch (e) {
  slackOk = false;
}

let airtableOk = true;
try {
  const airtableItem = $('Log to Airtable').first();
  airtableOk = !(airtableItem && airtableItem.json && airtableItem.json.error);
} catch (e) {
  airtableOk = false;
}

return [
  {
    json: {
      status: handoff.status,
      reason_code: handoff.reason_code,
      message_for_caller: handoff.message_for_caller,
      caller_phone: handoff.caller_phone,
      event_id: handoff.event_id,
      escalated_at: handoff.escalated_at,
      slack_notified: slackOk,
      airtable_logged: airtableOk
    }
  }
];
